	public void SendUpdateDigFossil(int stationIndex = -1) {
		if (!PlayerWork.isDigFossil || !isMainKasekihori)
			return;

		if (stationIndex != -1 && ugOnlinePlayerDatas[stationIndex].isJoinTonarihori)
			return;

		netDigData.data.digPos1 = tonarihoriList[0].Item2;
		netDigData.data.digPos2 = tonarihoriList[1].Item2;
		netDigData.data.zoneID = PlayerWork.zoneID;
		if (stationIndex != -1)
		{
			netDigData.SendReliableData(stationIndex);
		}
		else
		{
			IgnoreSendList.Clear();
			for (int i = 0; i < ugOnlinePlayerDatas.Count; i++)
			{
				if (ugOnlinePlayerDatas[i].isJoinTonarihori)
					IgnoreSendList.Add(i);
			}

			SendToSameZonePlayers(netDigData, true);
		}
	}
