	public void SendToSameZonePlayers<T>(global::Dpr.NetworkUtils.ANetData<T> netData, bool isReliable = true) where T : struct {
		if (!NetworkManager.Instance.IsJoinOtherPlayer())
			return;

		// `i` lives in <>c__DisplayClass105_0<T> (+0x10), captured by the Exists predicate
		for (int i = 0; i < ugOnlinePlayerDatas.Count; i++)
		{
			if (i == NetworkManager.Instance.MyStationIndex)
				continue;

			if (ugOnlinePlayerDatas[i].isNull)
				continue;

			if (IgnoreSendList.Exists(x => x == i))
				continue;

			ZoneID zoneID = PlayerWork.zoneID;
			if (PlayerWork.transitionZoneID != (ZoneID)(-1))
				zoneID = PlayerWork.transitionZoneID;

			if (ugOnlinePlayerDatas[i].nowZoneID != zoneID)
				continue;

			// loop unswitched on isReliable (rgctx +0x18 / +0x20)
			if (isReliable)
				netData.SendReliableData(i);
			else
				netData.SendUnReliableData(i);
		}

		IgnoreSendList.Clear();
	}
	public void SendToOtherZonePlayers<T>(global::Dpr.NetworkUtils.ANetData<T> netData, bool isReliable) where T : struct {
		if (!NetworkManager.Instance.IsJoinOtherPlayer())
			return;

		for (int i = 0; i < ugOnlinePlayerDatas.Count; i++)
		{
			if (i == NetworkManager.Instance.MyStationIndex)
				continue;

			if (ugOnlinePlayerDatas[i].isNull)
				continue;

			if (ugOnlinePlayerDatas[i].nowZoneID == PlayerWork.zoneID)
				continue;

			// loop unswitched on isReliable (rgctx +0 / +8)
			if (isReliable)
				netData.SendReliableData(i);
			else
				netData.SendUnReliableData(i);
		}
	}
	protected override void OnReceiveData(global::Dpr.NetworkUtils.INetData netData) {
		// every test is `X.DataID == netData.GetDataID` (static getter called before the interface slot-2 call)
		if (NetPosData.DataID == netData.GetDataID)
		{
			if (!isOtherScene)
				_OpcManager.SetNetData(netData);
		}
		else if (NetPosZoneData.DataID == netData.GetDataID)
		{
			NetPosZoneData posZoneData = (NetPosZoneData)netData;
			if (ugOnlinePlayerDatas[netData.FromStationIndex].nowZoneID != posZoneData.data.zoneID)
				_OpcManager.RemoveCharacter(netData.FromStationIndex, true);

			if (_OpcManager.GetOpc(netData.FromStationIndex) != null)
				_OpcManager.RemoveCharacter(netData.FromStationIndex, true);

			// SetPlayerPosition inlined (flag 0x4cbd47e @01b1249c)
			SetPlayerPosition(netData.FromStationIndex, posZoneData.data.pos);
		}
		else if (NetZoneData.DataID == netData.GetDataID)
		{
			OnReceiveZoneData(netData);
		}
		else if (NetCharacterStateData.DataID == netData.GetDataID)
		{
			if (!isOtherScene)
				OnReceiveStateData(netData);
		}
		else if (NetUgJoinData.DataID == netData.GetDataID)
		{
			if (!isOtherScene)
				OnReceiveJoinData(netData);
		}
		else if (NetRequestData.DataID == netData.GetDataID)
		{
			OnReceiveRequestData(netData);
		}
		else if (NetSecretBaseInfo.DataID == netData.GetDataID)
		{
			OnReceiveSecretBase_Info(netData);
		}
		else if (NetSecretBaseData.DataID == netData.GetDataID)
		{
			// OnReceiveSecretBaseData inlined (flag 0x4cbd476 @01b126e0)
			OnReceiveSecretBaseData(netData);
		}
		else if (NetSecretBaseUpdate.DataID == netData.GetDataID)
		{
			OnReceiveSecretBaseUpdate(netData);
		}
		else if (NetDigData.DataID == netData.GetDataID)
		{
			OnReceiveDigPointData(netData);
		}
		else if (NetJoinDigPermission.DataID == netData.GetDataID)
		{
			OnReceiveJoinDigPermission((NetJoinDigPermission)netData);
		}
		else if (NetDigAttackData.DataID == netData.GetDataID || NetDigEndData.DataID == netData.GetDataID
			|| NetDigJoinData.DataID == netData.GetDataID || NetDigJoinMemberCount.DataID == netData.GetDataID)
		{
			// the four matches share one `b OnReceiveDigJoinData` @01b12b10
			OnReceiveDigJoinData(netData);
		}
		else if (NetPlayerNameData.DataID == netData.GetDataID)
		{
			OnReceivePlayerNameData(netData);
		}
		else if (NetKousekiAdd.DataID == netData.GetDataID)
		{
			OnReceiveAddKouseki(netData);
		}
		else if (NetBonusStart.DataID == netData.GetDataID)
		{
			OnReceiveBonusStart(netData);
		}
		else if (NetRemainBonusTime.DataID == netData.GetDataID)
		{
			OnReceiveRemainBonusTime(netData);
		}
		else if (NetKousekiCount.DataID == netData.GetDataID)
		{
			OnReceiveKousekiCount(netData);
		}
		else if (NetNaminoriData.DataID == netData.GetDataID)
		{
			if (!isOtherScene)
				OnReceiveNaminoriData(netData);
		}
		else if (NetDigTableData.DataID == netData.GetDataID)
		{
			OnReceiveDigTableData(netData);
		}
	}
	private void OnReceiveJoinData(global::Dpr.NetworkUtils.INetData netData) {
		NetUgJoinData joinData = (NetUgJoinData)netData;
		// zoneID read before the FromStationIndex interface call (@01b13480)
		short zoneID = joinData.data.zoneID;
		SetZoneID(netData.FromStationIndex, (ZoneID)zoneID);
		// SetPlayerPosition inlined (flag 0x4cbd47e @01b1355c)
		SetPlayerPosition(netData.FromStationIndex, joinData.data.InitPos);
		if (PlayerWork.zoneID == (ZoneID)zoneID)
		{
			_OpcManager.CreateCharacter(netData);
			netReqData.data.RequestDataID = NetCharacterStateData.DataID;
			// SendReqData inlined twice (flag 0x4cbd468); FromStationIndex read as the class property (+0x24)
			SendReqData(joinData.FromStationIndex, "StateData");
			netReqData.data.RequestDataID = NetNaminoriData.DataID;
			SendReqData(joinData.FromStationIndex, "NaminoriData");
		}
	}
	private void OnReceiveStateData(global::Dpr.NetworkUtils.INetData netData) {
		NetCharacterStateData stateData = (NetCharacterStateData)netData;
		// state byte read before the SetNetData virtual call (@01b13344)
		OpcState.OnlineState state = (OpcState.OnlineState)stateData.data.state;
		_OpcManager.SetNetData(netData);
		ugOnlinePlayerDatas[netData.FromStationIndex].onlineState = state;
	}
	private void OnReceiveZoneData(global::Dpr.NetworkUtils.INetData netData) {
		NetZoneData zoneData = (NetZoneData)netData;
		// zoneID read before the FromStationIndex interface call (@01b13044)
		ZoneID zoneID = zoneData.data.zoneID;
		SetZoneID(netData.FromStationIndex, zoneID);
		// SetPlayerPosition inlined (flag 0x4cbd47e @01b1311c)
		SetPlayerPosition(netData.FromStationIndex, zoneData.data.pos);
		if (zoneID == PlayerWork.zoneID)
			SendOnOtherPlayerToSameZone(netData.FromStationIndex);
		else
			_OpcManager.RemoveCharacter(netData.FromStationIndex, true);
	}
	private void OnReceiveRequestData(global::Dpr.NetworkUtils.INetData netData) {
		NetRequestData requestData = (NetRequestData)netData;
		// both read once before the first DataID call (@01b13748 / @01b13750)
		byte requestDataID = requestData.data.RequestDataID;
		int fromStationIndex = requestData.FromStationIndex;
		if (requestDataID == NetJoinData.DataID)
		{
			// SendMyJoinData inlined (flag 0x4cbd467 @01b13764)
			SendMyJoinData(fromStationIndex);
		}
		else if (requestDataID == NetSecretBaseData.DataID)
		{
			SendMySecretBaseData(fromStationIndex);
		}
		else if (requestDataID == NetCharacterStateData.DataID)
		{
			// SendStateData inlined (flag 0x4cbd46f @01b13960) with the INetData.FromStationIndex interface call
			SendStateData(netData.FromStationIndex);
		}
		else if (requestDataID == NetDigData.DataID)
		{
			if (PlayerWork.isDigFossil)
				SendUpdateDigFossil(fromStationIndex);
		}
		else if (requestDataID == NetSecretBaseUpdate.NoticeID)
		{
			if (UgFieldManager.Instance.IsUseTargetSecretBase(fromStationIndex))
			{
				netReqData.data.RequestDataID = NetSecretBaseUpdate.DataID;
				// SendReqData inlined (flag 0x4cbd468 @01b138f4)
				SendReqData(fromStationIndex, "SecretBase UpdateData");
			}
		}
		else if (requestDataID == NetSecretBaseUpdate.DataID)
		{
			netSecretBaseUpdate.data = PlayerWork.ugSaveData.ugRecord.myBase;
			netSecretBaseUpdate.SendReliableData(fromStationIndex);
		}
		else if (requestDataID == NetNaminoriData.DataID)
		{
			netNaminoriData.SendReliableData(netData.FromStationIndex);
		}
		else if (requestDataID == NetDigTableData.DataID)
		{
			if (IsDigTableReady)
			{
				netDigTableData.data = UgFieldManager.Instance.ugDigGroupList;
				netDigTableData.SendReliableData(netData.FromStationIndex);
			}
		}
	}
	private void OnReceiveSecretBase_Info(global::Dpr.NetworkUtils.INetData netData) {
		NetSecretBaseInfo secretBaseInfo = (NetSecretBaseInfo)netData;
		// the station index is read once (w21) and reused by CreateSecretBaseRandom (@01b13d90)
		int stationIndex = netData.FromStationIndex;
		// SetSecretBaseInfo inlined (flag 0x4cbd47d @01b13cec)
		SetSecretBaseInfo(stationIndex, secretBaseInfo.data);
		if (secretBaseInfo.data.zoneID == PlayerWork.zoneID)
			UgFieldManager.Instance.CreateSecretBaseRandom(stationIndex);
