	private void OnReceiveDigTableData(global::Dpr.NetworkUtils.INetData netData) {
		if (IsDigTableReady)
			return;

		// the cast is checked before UgFieldManager's class-init (@01b151a4)
		NetDigTableData digTableData = (NetDigTableData)netData;
		UgFieldManager.Instance.ugDigGroupList = digTableData.data;
		UgFieldManager.Instance.DeleteAllDigPoints();
		UgFieldManager.Instance.CreateDigPoints(NetworkManager.Instance.MyStationIndex);
		IsDigTableReady = true;
