	private void OnReceiveJoinDigPermission(global::Dpr.NetworkUtils.NetJoinDigPermission permission) {
		OnDigFossilJoinPermission?.Invoke(permission.data.isOK);
		if (permission.data.isOK)
		{
			digFossileMainPlayerStationIndex = permission.FromStationIndex;
			UgFieldManager.Instance.DeleteTargetTonarihori(permission.FromStationIndex);
			SetReserveEmoticon();
			// SetAndSendMyPlayerState (flag 0x4cbd465) / SetMyEmoticon (0x4cbd466) inlined @01b140c0–01b14198
			SetAndSendMyPlayerState(OpcState.OnlineState.NOW_DIG_FOSILE);
		}
		else
		{
			UgFieldManager.digData.PrevSceneisDigFossil = false;
			UgFieldManager.isEnableInput = true;
		}
	}
	private void OnReceiveDigJoinData(global::Dpr.NetworkUtils.INetData netData) {
		if (NetDigJoinData.DataID == netData.GetDataID)
		{
			bool isOK = CheckJoinTonarihori((NetDigJoinData)netData);
			// SendJoinDigPermission inlined (flag 0x4cbd46c @01b14490)
			SendJoinDigPermission(netData.FromStationIndex, isOK);
			if (isOK)
			{
				ugOnlinePlayerDatas[netData.FromStationIndex].isJoinTonarihori = true;
				DigJoinMemberCount++;
				SendUpdateDigFossil(-1);
				SendDigJoinMemberCount();
			}
		}
		else if (NetDigEndData.DataID == netData.GetDataID)
		{
			UgFieldManager.Instance.DeleteTargetTonarihori(netData.FromStationIndex);
			if (netData.FromStationIndex == digFossileMainPlayerStationIndex)
				digFossileMainPlayerStationIndex = -1;

			OnDigEndOtherPlayer?.Invoke(netData.FromStationIndex);
		}
		else if (NetDigAttackData.DataID == netData.GetDataID)
		{
			if (PlayerWork.isDigFossil)
				OnReceiveDigFossilNetData?.Invoke(netData);
		}
		else if (NetDigJoinMemberCount.DataID == netData.GetDataID)
		{
			if (PlayerWork.isDigFossil)
			{
				DigTonariMemberCount = ((NetDigJoinMemberCount)netData).data.Value - 1;
				OnReceiveDigFossilNetData?.Invoke(netData);
			}
		}
	}
