	private void OnReceiveAddKouseki(global::Dpr.NetworkUtils.INetData netData) {
		// read before the isKousekiBonus call (@01b149c4)
		int num = ((NetKousekiAdd)netData).data.Value;
		if (!isKousekiBonus)
		{
			KousekiCount += (byte)num;
			UgFieldManager.Instance.UpdateKousekiUI();
			if (IsKousekiFull)
				Dpr.UnderGround.LightStone.LightStoneManager.StartBonusTime();
		}
	}
	private void OnReceiveBonusStart(global::Dpr.NetworkUtils.INetData netData) {
		if (!isKousekiBonus)
			Dpr.UnderGround.LightStone.LightStoneManager.StartBonusTime();
	}
	private void OnReceiveRemainBonusTime(global::Dpr.NetworkUtils.INetData netData) {
		NetRemainBonusTime remainBonusTime = (NetRemainBonusTime)netData;
		// the bonus state is fetched before the time compare (`bl get_isKousekiBonus` @01b14d38, used @01b14d9c)
		bool isBonus = isKousekiBonus;
		if (KousekiBonusTime < remainBonusTime.data.Value)
		{
			if (isBonus)
				KousekiBonusTime = remainBonusTime.data.Value;
			else
				UgFieldManager.Instance.StartKousekiBonus(remainBonusTime.data.Value);
		}
	}
	private void OnReceiveKousekiCount(global::Dpr.NetworkUtils.INetData netData) {
		if (isKousekiBonus)
			return;

		// read once and stored unchanged (@01b14f20 / @01b14fbc)
		int count = ((NetKousekiCount)netData).data.Value;
		if (count > KousekiCount)
		{
			KousekiCount = (byte)count;
			UgFieldManager.Instance.UpdateKousekiUI();
		}
	}
