		netJoinData.data.avatarId = (byte)PlayerWork.playerFashion;
		netJoinData.data.colorId = (byte)PlayerWork.colorID;
		// one get_position call, read before netJoinData is loaded (@01b10c98 / @01b10c9c)
		Vector3 position = myPlayer.transform.position;
