	private void OnCreateOpc(int stationIndex) {
		OpcController opc = _OpcManager.GetOpc(stationIndex);
		// both read before the Unity null test (@01b159e8 / @01b15a14)
		OpcState.OnlineState onlineState = ugOnlinePlayerDatas[stationIndex].onlineState;
		bool isNaminori = ugOnlinePlayerDatas[stationIndex].isNaminori;
		if (opc == null)
			return;

		UgOpcController ugOpcController = (UgOpcController)opc;
		ugOpcController.SetOpcOnlineState(onlineState);
		ugOpcController.SetNaminoriState(isNaminori);
	}
	private bool CheckJoinTonarihori(global::Dpr.NetworkUtils.NetDigJoinData netData) {
		// <>c__DisplayClass135_0 is created at method entry (@01b154a0); it captures `position` (+0x10)
		if (!PlayerWork.isDigFossil)
			return false;

		Vector2Int position = netData.data.TonariHoriPosition;
		int index = tonarihoriList.FindIndex(x => x.Item2 == position);
		if (index == -1)
			return false;

		if (tonarihoriList[index].Item1 != -1)
			return false;

		tonarihoriList[index] = (netData.FromStationIndex, new Vector2Int(-1, -1));
		return true;
	}
